package dev.zomboid.mts;
import java.util.*;
public class TelemetryTest{
 public static class Vehicle {public Definition definition=new Definition();public double velocity=1;public Collection<Engine> engines=new ArrayList<>();public Tank fuelTank=new Tank();}
 public static class Definition{public String systemName="bell206",packID="mtsofficialpack";public Motor motorized=new Motor();public List<Part> parts=List.of(new Part());}
 public static class Motor{public boolean isAircraft=true;}public static class Part{public List<String> types=List.of("engine_helicopter_turboshaft");}
 public static class Engine{public double rpm=2400,fuelFlow=2;public boolean running=true;}public static class Tank{public double getFluidLevel(){return 5000;}public int getMaxLevel(){return 10000;}}
 public static class Gui{public Vehicle vehicle;public Gui(Vehicle v){vehicle=v;}}
 public static void main(String[] args){Vehicle v=new Vehicle();Engine e=new Engine();v.engines.add(e);String[] rows=HudTelemetry.rows(v);if(!rows[0].contains("72 km/h")||!rows[0].contains("2400"))throw new AssertionError(Arrays.toString(rows));if(!rows[1].contains("50%")||!rows[1].contains("5.0 / 10.0 L"))throw new AssertionError();if(!rows[2].contains("2.40 L/min"))throw new AssertionError();v.engines.add(new Engine());rows=HudTelemetry.rows(v);if(!rows[0].contains("1: 2400")||!rows[0].contains("2: 2400")||!rows[2].contains("4.80"))throw new AssertionError();v.engines.forEach(n->n.running=false);if(!HudTelemetry.rows(v)[2].contains("0.00"))throw new AssertionError();if(!HudTelemetry.special(v)||HudTelemetry.width(new Gui(v),400)!=260||HudTelemetry.height(new Gui(v),100)!=54)throw new AssertionError();v.definition.systemName="boat";v.definition.motorized.isAircraft=false;v.definition.parts=List.of();if(!HudTelemetry.special(v))throw new AssertionError("boat");v.definition.systemName="comanche";v.definition.motorized.isAircraft=true;v.definition.parts.getClass();if(!HudTelemetry.special(v))throw new AssertionError("plane");v.engines.clear();v.fuelTank=null;v.velocity=Double.NaN;rows=HudTelemetry.rows(v);if(Arrays.toString(rows).contains("NaN")||!rows[0].contains("RPM 0"))throw new AssertionError();System.out.println("PASS helicopter/plane/boat detection, 260x54 compact HUD, multi-engine RPM, real L/min conversion, remaining liters, stopped engines and missing-data guards");}}
